package com.shopsphere.swing;
import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.*;
/** Desktop admin product/inventory viewer. Connects through JDBC; credentials require ADMIN role. */
public class AdminDesktop {
 private static Connection open()throws SQLException{return DriverManager.getConnection(System.getenv().getOrDefault("SHOPSPHERE_DB_URL","jdbc:mysql://localhost:3306/shopsphere"),System.getenv().getOrDefault("SHOPSPHERE_DB_USER","root"),System.getenv().getOrDefault("SHOPSPHERE_DB_PASSWORD",""));}
 public static void main(String[] args){SwingUtilities.invokeLater(()->{try{UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());}catch(Exception ignored){}showLogin();});}
 static void showLogin(){JTextField email=new JTextField(22);JPasswordField pass=new JPasswordField(22);JPanel p=new JPanel(new GridLayout(2,2,10,10));p.add(new JLabel("Admin email"));p.add(email);p.add(new JLabel("Password"));p.add(pass);if(JOptionPane.showConfirmDialog(null,p,"ShopSphere admin",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try(Connection c=open();PreparedStatement q=c.prepareStatement("SELECT password FROM users WHERE email=? AND role='ADMIN' AND status=TRUE")){q.setString(1,email.getText());try(ResultSet r=q.executeQuery()){if(r.next() && org.mindrot.jbcrypt.BCrypt.checkpw(new String(pass.getPassword()),r.getString(1))){showDashboard();return;}}}catch(Exception e){JOptionPane.showMessageDialog(null,"Connection failed: "+e.getMessage());return;}JOptionPane.showMessageDialog(null,"Invalid admin login");}
 static void showDashboard(){JFrame frame=new JFrame("ShopSphere • Admin Desktop");frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);frame.setSize(860,520);frame.setLocationRelativeTo(null);DefaultTableModel m=new DefaultTableModel(new String[]{"ID","Product","Brand","Price","Stock"},0){public boolean isCellEditable(int r,int c){return false;}};JTable table=new JTable(m);JButton refresh=new JButton("Refresh products");JButton update=new JButton("Update selected stock");JPanel buttons=new JPanel();buttons.add(refresh);buttons.add(update);frame.add(buttons,BorderLayout.NORTH);frame.add(new JScrollPane(table),BorderLayout.CENTER);
 Runnable reload=()->{m.setRowCount(0);try(Connection c=open();PreparedStatement q=c.prepareStatement("SELECT product_id,name,brand,price,stock FROM products ORDER BY product_id");ResultSet r=q.executeQuery()){while(r.next())m.addRow(new Object[]{r.getInt(1),r.getString(2),r.getString(3),r.getBigDecimal(4),r.getInt(5)});}catch(Exception e){JOptionPane.showMessageDialog(frame,e.getMessage());}};refresh.addActionListener(e->reload.run());update.addActionListener(e->{int row=table.getSelectedRow();if(row<0)return;int id=(int)m.getValueAt(row,0);String qty=JOptionPane.showInputDialog(frame,"New stock count:");if(qty==null)return;try{int n=Integer.parseInt(qty);if(n<0)throw new IllegalArgumentException();try(Connection c=open();PreparedStatement q=c.prepareStatement("UPDATE products SET stock=? WHERE product_id=?")){q.setInt(1,n);q.setInt(2,id);q.executeUpdate();}reload.run();}catch(Exception ex){JOptionPane.showMessageDialog(frame,"Invalid stock or database error");}});reload.run();frame.setVisible(true);}
}
